import React from 'react';
import { StyleSheet, View } from 'react-native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import ProfileScreen from '../screens/ProfileScreen';
import PrescriptionsScreen from '../screens/PrescriptionsScreen';
import AppointmentsScreen from '../screens/AppointmentsScreen';
import CorrespondenceScreen from '../screens/Correspondence';
import DependantsScreen from '../screens/DependantsScreen';
import { FontAwesome } from '@expo/vector-icons';
//import CallButton from '../components/callButton';
import CallButton from '../components/callButton';

const Tab = createBottomTabNavigator();

const RootNavigator = () => {
    return (
        <View style={{ flex: 1 }}>
            <Tab.Navigator
                initialRouteName="Profile"
                screenOptions={{
                    headerShown: false,
                    tabBarActiveTintColor: '#FF6F00',
                    tabBarInactiveTintColor: 'gray',
                }}
            >
                <Tab.Screen
                    name="Profile"
                    component={ProfileScreen}
                    options={{
                        tabBarIcon: ({ color, size }) => (
                            <FontAwesome name="user" size={size} color={color} />
                        ),
                    }}
                />
                <Tab.Screen
                    name="Appointments"
                    component={AppointmentsScreen}
                    options={{
                        tabBarIcon: ({ color, size }) => (
                            <FontAwesome name="calendar" size={size} color={color} />
                        ),
                    }}
                />
                <Tab.Screen
                    name="Correspondence"
                    component={CorrespondenceScreen}
                    options={{
                        tabBarIcon: ({ color, size }) => (
                            <FontAwesome name="file-text-o" size={size} color={color} />
                        ),
                    }}
                />
                <Tab.Screen
                    name="Dependants"
                    component={DependantsScreen}
                    options={{
                        tabBarIcon: ({ color, size }) => (
                            <FontAwesome name="child" size={size} color={color} />
                        ),
                    }}
                />
                <Tab.Screen
                    name="Prescriptions"
                    component={PrescriptionsScreen}
                    options={{
                        tabBarIcon: ({ color, size }) => (
                            <FontAwesome name="medkit" size={size} color={color} />
                        ),
                    }}
                />
            </Tab.Navigator>

            {/* Floating Call Button, always on top of all tabs */}
            <CallButton />
        </View>
    );
};

export default RootNavigator; window