import React, { useEffect, useRef, useState } from "react";
import JsSIP from "jssip";
import AsyncStorage from "@react-native-async-storage/async-storage";
import Updater from "./Updater";

const CallButton = () => {
    const [credentials, setCredentials] = useState(null);
    const [isRegistered, setIsRegistered] = useState(false);
    const [callStatus, setCallStatus] = useState("idle"); // idle, dialing, progress, inCall
    const uaRef = useRef(null);
    const sessionRef = useRef(null);
    const remoteAudioRef = useRef(new Audio());

    // Initialize remote audio
    useEffect(() => {
        remoteAudioRef.current.autoplay = true;
    }, []);

    // Fetch SIP credentials
    const fetchUpdatedData = async () => {
        try {
            const updatedUserData = await Updater();
            if (updatedUserData?.callCredentials) {
                setCredentials(updatedUserData.callCredentials);
            } else {
                const userDataString = await AsyncStorage.getItem("userData");
                const parsedData = userDataString ? JSON.parse(userDataString) : {};
                setCredentials(parsedData?.callCredentials);
            }
        } catch (error) {
            console.error("Error fetching credentials:", error);
        }
    };

    useEffect(() => {
        fetchUpdatedData();
    }, []);

    // Initialize JsSIP UA
    useEffect(() => {
        if (!credentials || uaRef.current) return; // already initialized

        try {
            const socket = new JsSIP.WebSocketInterface(credentials.server);

            const configuration = {
                sockets: [socket],
                uri: `sip:${credentials.username}@${credentials.sipURI}`,
                password: credentials.password,
                register: true,
                session_timers: false,
                trace_sip: true,
            };

            const ua = new JsSIP.UA(configuration);
            uaRef.current = ua;

            ua.on("connected", () => console.log("WebSocket connected ✅"));
            ua.on("registered", () => {
                console.log("REGISTERED ✅");
                setIsRegistered(true);
            });
            ua.on("registrationFailed", (e) => {
                console.error("REGISTRATION FAILED ❌", e.cause);
                setIsRegistered(false);
            });
            ua.on("disconnected", () => {
                console.log("Disconnected");
                setIsRegistered(false);
            });

            ua.start();
        } catch (err) {
            console.error("UA Init error:", err);
        }

        // Cleanup UA on unmount
        return () => {
            if (uaRef.current) uaRef.current.stop();
        };
    }, [credentials]);

    // Make a call
    const handleCall = async () => {
        if (!uaRef.current || !isRegistered) {
            alert("SIP not ready or not registered");
            return;
        }

        if (callStatus !== "idle") {
            alert("Call already in progress");
            return;
        }

        try {
            await navigator.mediaDevices.getUserMedia({ audio: true });
        } catch (err) {
            console.error("Microphone access denied:", err);
            return;
        }

        const target = `sip:1000@${credentials.sipURI}`; // change target as needed

        const session = uaRef.current.call(target, {
            mediaConstraints: { audio: true, video: false },
            pcConfig: { iceServers: [{ urls: "stun:stun.l.google.com:19302" }] },
            rtcOfferConstraints: { offerToReceiveAudio: 1, offerToReceiveVideo: 0 },
        });

        sessionRef.current = session;
        setCallStatus("dialing");

        // Attach remote audio correctly
        session.on("confirmed", () => {
            setCallStatus("inCall");

            // Attach any already negotiated audio tracks
            if (session.connection.getReceivers) {
                session.connection.getReceivers().forEach((receiver) => {
                    if (receiver.track.kind === "audio") {
                        remoteAudioRef.current.srcObject = new MediaStream([receiver.track]);
                        remoteAudioRef.current.play().catch(console.log);
                    }
                });
            }

            // Listen for remote tracks added later
            session.connection.addEventListener("track", (event) => {
                remoteAudioRef.current.srcObject = event.streams[0];
                remoteAudioRef.current.play().catch(console.log);
            });
        });

        session.on("progress", () => setCallStatus("progress"));
        session.on("failed", () => {
            setCallStatus("idle");
            sessionRef.current = null;
        });
        session.on("ended", () => {
            setCallStatus("idle");
            sessionRef.current = null;
        });
    };

    // End the call
    const handleHangup = () => {
        if (sessionRef.current) {
            sessionRef.current.terminate();
            sessionRef.current = null;
            setCallStatus("idle");
            console.log("Call terminated by user");
        }
    };

    return (
        <div>
            <button
                onClick={handleCall}
                disabled={!isRegistered || callStatus !== "idle"}
                style={{
                    position: "absolute",
                    top: 60,
                    right: 20,
                    width: 60,
                    height: 60,
                    borderRadius: 30,
                    backgroundColor: isRegistered ? "#22c55e" : "gray",
                    cursor: isRegistered ? "pointer" : "not-allowed",
                }}
            >
                📞
            </button>

            {callStatus !== "idle" && (
                <button
                    onClick={handleHangup}
                    style={{
                        position: "absolute",
                        top: 140,
                        right: 20,
                        width: 60,
                        height: 60,
                        borderRadius: 30,
                        backgroundColor: "#ef4444",
                        cursor: "pointer",
                    }}
                >
                    ✖️
                </button>
            )}
        </div>
    );
};

export default CallButton;